package io.github.diodeme.ji.artifact;

import java.util.OptionalLong;

/** Inclusive byte range. An empty end means through end-of-object. */
public record ByteRange(long start, OptionalLong endInclusive) {
    public ByteRange {
        if (start < 0) throw new IllegalArgumentException("range start must be non-negative");
        endInclusive = endInclusive == null ? OptionalLong.empty() : endInclusive;
        if (endInclusive.isPresent() && endInclusive.getAsLong() < start) {
            throw new IllegalArgumentException("range end must not precede start");
        }
    }

    public ByteRange(long start, long endInclusive) {
        this(start, OptionalLong.of(endInclusive));
    }

    public static ByteRange all() {
        return new ByteRange(0, OptionalLong.empty());
    }
}
